import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/math-average-adv.svg",u=JSON.parse('{"title":"小学奥数进阶：平均数问题的“移多补少”","description":"平均数不仅是一个计算公式，更是一种“平衡”的思维。本文详解平均数的定义、移多补少法以及复杂的加权平均思想。","frontmatter":{"title":"小学奥数进阶：平均数问题的“移多补少”","date":"2026-02-08T10:30:00.000Z","categories":["数学"],"tags":["小学数学","奥数","平均数"],"description":"平均数不仅是一个计算公式，更是一种“平衡”的思维。本文详解平均数的定义、移多补少法以及复杂的加权平均思想。","cover":"/img/math-average-adv.svg","top_img":"/img/banner.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-average-problems.md","filePath":"posts/primary-math-olympiad-average-problems.md","lastUpdated":null}'),r={name:"posts/primary-math-olympiad-average-problems.md"};function l(o,a,e,c,i,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="小学奥数进阶-平均数问题的-移多补少" tabindex="-1">小学奥数进阶：平均数问题的“移多补少” <a class="header-anchor" href="#小学奥数进阶-平均数问题的-移多补少" aria-label="Permalink to &quot;小学奥数进阶：平均数问题的“移多补少”&quot;">​</a></h1><h2 id="一、-核心定义" tabindex="-1">一、 核心定义 <a class="header-anchor" href="#一、-核心定义" aria-label="Permalink to &quot;一、 核心定义&quot;">​</a></h2><p>平均数是指一组数据的和除以这组数据的个数。</p><ul><li><strong>平均数 = 总和 ÷ 总个数</strong></li><li><strong>总和 = 平均数 × 总个数</strong></li></ul><hr><h2 id="二、-核心思维-移多补少" tabindex="-1">二、 核心思维：移多补少 <a class="header-anchor" href="#二、-核心思维-移多补少" aria-label="Permalink to &quot;二、 核心思维：移多补少&quot;">​</a></h2><p>想象有几根长短不一的柱子，把长出的部分切下来，补到短的部分，直到所有柱子一样高。这“一样高”的高度就是平均数。</p><p><img src="'+p+'" alt="平均数移多补少图解"></p><hr><h2 id="三、-典型题型解析" tabindex="-1">三、 典型题型解析 <a class="header-anchor" href="#三、-典型题型解析" aria-label="Permalink to &quot;三、 典型题型解析&quot;">​</a></h2><h3 id="_1-寻找消失的数值" tabindex="-1">1. 寻找消失的数值 <a class="header-anchor" href="#_1-寻找消失的数值" aria-label="Permalink to &quot;1. 寻找消失的数值&quot;">​</a></h3><p><strong>例题</strong>：小明前 4 次数学测试的平均分是 92 分。第 5 次测试后，5 次的平均分变成了 93 分。第 5 次测了多少分？</p><ul><li><strong>常规解法</strong>： <ul><li>前 4 次总分：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>2</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>3</mn><mn>6</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">92 \\times 4 = 368</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mord mathrm">8</span></span></span></span>。</li><li>前 5 次总分：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>3</mn><mo>×</mo><mn>5</mn><mo>=</mo><mn>4</mn><mn>6</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">93 \\times 5 = 465</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">3</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">6</span><span class="mord mathrm">5</span></span></span></span>。</li><li>第 5 次分数：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>6</mn><mn>5</mn><mo>−</mo><mn>3</mn><mn>6</mn><mn>8</mn><mo>=</mo><mn>9</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">465 - 368 = 97</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">6</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mord mathrm">6</span><span class="mord mathrm">8</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">7</span></span></span></span> 分。</li></ul></li><li><strong>巧妙思维（移多补少）</strong>： <ul><li>第 5 次测完后，平均分提高了 1 分。</li><li>这意味着第 5 次的分数不仅要达到新的平均分 93，还要把前 4 次欠缺的各 1 分给补上。</li><li>第 5 次分数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>3</mn><mo>+</mo><mn>4</mn><mo>×</mo><mn>1</mn><mo>=</mo><mn>9</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">93 + 4 \\times 1 = 97</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">7</span></span></span></span> 分。</li></ul></li></ul><h3 id="_2-基准数法-简化计算" tabindex="-1">2. 基准数法（简化计算） <a class="header-anchor" href="#_2-基准数法-简化计算" aria-label="Permalink to &quot;2. 基准数法（简化计算）&quot;">​</a></h3><p><strong>例题</strong>：求 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>8</mn><mo separator="true">,</mo><mn>9</mn><mn>6</mn><mo separator="true">,</mo><mn>1</mn><mn>0</mn><mn>3</mn><mo separator="true">,</mo><mn>1</mn><mn>0</mn><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mn>0</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">98, 96, 103, 101, 102</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">8</span><span class="mpunct">,</span><span class="mord mathrm">9</span><span class="mord mathrm">6</span><span class="mpunct">,</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">3</span><span class="mpunct">,</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">1</span><span class="mpunct">,</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">2</span></span></span></span> 的平均数。</p><ul><li><strong>解析</strong>： <ul><li>找基准数 100。</li><li>差值分别为：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>−</mo><mn>2</mn><mo separator="true">,</mo><mo>−</mo><mn>4</mn><mo separator="true">,</mo><mo>+</mo><mn>3</mn><mo separator="true">,</mo><mo>+</mo><mn>1</mn><mo separator="true">,</mo><mo>+</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">-2, -4, +3, +1, +2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.8388800000000001em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord">−</span><span class="mord mathrm">2</span><span class="mpunct">,</span><span class="mord">−</span><span class="mord mathrm">4</span><span class="mpunct">,</span><span class="mord">+</span><span class="mord mathrm">3</span><span class="mpunct">,</span><span class="mord">+</span><span class="mord mathrm">1</span><span class="mpunct">,</span><span class="mord">+</span><span class="mord mathrm">2</span></span></span></span>。</li><li>差值总和：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mo>−</mo><mn>2</mn><mo>)</mo><mo>+</mo><mo>(</mo><mo>−</mo><mn>4</mn><mo>)</mo><mo>+</mo><mn>3</mn><mo>+</mo><mn>1</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">(-2) + (-4) + 3 + 1 + 2 = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord">−</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">+</span><span class="mopen">(</span><span class="mord">−</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">0</span></span></span></span>。</li><li>平均数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>0</mn><mo>÷</mo><mn>5</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">100 + 0 \\div 5 = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>。</li></ul></li></ul><h3 id="_3-加权平均思想" tabindex="-1">3. 加权平均思想 <a class="header-anchor" href="#_3-加权平均思想" aria-label="Permalink to &quot;3. 加权平均思想&quot;">​</a></h3><p><strong>例题</strong>：某班男生 20 人，平均身高 150 厘米；女生 30 人，平均身高 145 厘米。全班平均身高是多少？</p><ul><li><strong>错误算法</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mn>5</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>4</mn><mn>5</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>4</mn><mn>7</mn><mi mathvariant="normal">.</mi><mn>5</mn></mrow><annotation encoding="application/x-tex">(150 + 145) \\div 2 = 147.5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">7</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span></span></span></span>（错！因为人数不等）。</li><li><strong>正确算法</strong>： <ul><li>总身高 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mn>0</mn><mo>×</mo><mn>2</mn><mn>0</mn><mo>+</mo><mn>1</mn><mn>4</mn><mn>5</mn><mo>×</mo><mn>3</mn><mn>0</mn><mo>=</mo><mn>3</mn><mn>0</mn><mn>0</mn><mn>0</mn><mo>+</mo><mn>4</mn><mn>3</mn><mn>5</mn><mn>0</mn><mo>=</mo><mn>7</mn><mn>3</mn><mn>5</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">150 \\times 20 + 145 \\times 30 = 3000 + 4350 = 7350</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">7</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span></span></span></span> 厘米。</li><li>总人数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>+</mo><mn>3</mn><mn>0</mn><mo>=</mo><mn>5</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 + 30 = 50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span></span></span></span> 人。</li><li>平均身高 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>7</mn><mn>3</mn><mn>5</mn><mn>0</mn><mo>÷</mo><mn>5</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>4</mn><mn>7</mn></mrow><annotation encoding="application/x-tex">7350 \\div 50 = 147</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">7</span><span class="mord mathrm">3</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span><span class="mord mathrm">7</span></span></span></span> 厘米。</li></ul></li></ul><hr><h2 id="四、-总结提升" tabindex="-1">四、 总结提升 <a class="header-anchor" href="#四、-总结提升" aria-label="Permalink to &quot;四、 总结提升&quot;">​</a></h2><ol><li><strong>公式是基础</strong>：求平均数离不开“总和”与“总个数”。</li><li><strong>平衡是灵魂</strong>：利用“移多补少”可以大幅简化计算。</li><li><strong>加权要注意</strong>：当各组人数不同时，不能直接取平均数的平均数。</li></ol><hr><h2 id="五、-举一反三-练习题" tabindex="-1">五、 举一反三（练习题） <a class="header-anchor" href="#五、-举一反三-练习题" aria-label="Permalink to &quot;五、 举一反三（练习题）&quot;">​</a></h2><ol><li>5 个数的平均数是 18，如果把其中一个数改为 12，平均数就变成了 16。原来这个数是多少？</li><li>老师在黑板上写了 7 个连续的自然数，平均数是 20。这 7 个数中最大的一个是几？</li></ol><hr><p><em>提示：平均数就是“削峰填谷”的过程！</em></p>',27)])])}const g=s(r,[["render",l]]);export{u as __pageData,g as default};
